const s = wb.getWorksheet('Sheet1');
const vals = s.getRange('A3:A16').getValues().map(r => r[0]);
const seen = new Map(); const dups = [];
vals.forEach((v, i) => { const k = typeof v + ':' + v; if (seen.has(k)) dups.push([i + 3, v, seen.get(k)]); else seen.set(k, i + 3); });
log(JSON.stringify(dups));
log(JSON.stringify(vals.map(v => typeof v)));
log(s.getRegions('style'));

